    private readonly DataGridView board = Grid("WeekBoard"), shifts = Grid("WeekShifts"), assignments = Grid("WeekAssignments"), leaves = Grid("WeekLeaves"), legacy = Grid("LegacyLeaves"), templates = Grid("ShiftTemplates");
