    private readonly Button copyWeek = Button("Haftayı kopyala / önizle…");
    private readonly Button create = Button("Şablondan vardiya…"), add = Button("Vardiyaya kişi ata…"), publish = Button("Yayınla…"), cancel = Button("Vardiyayı iptal et…"), remove = Button("Atamayı iptal et…"), request = Button("İzin talebi…"), accept = Button("İzni onayla…"), reject = Button("İzni reddet…"), cancelLeave = Button("İzni iptal et…"), newTemplate = Button("Yeni şablon…"), editTemplate = Button("Şablonu düzenle…");
    private DataTable templateData = new(), teamData = new(); private bool loading;
    private SchedulingService Service => new(AppDatabase.ConnectionString, User);
    private static Button Button(string text) => new() { Text = text, AutoSize = true };
