    private DateTime First { get { var day = week.Value.Date; return DateTime.SpecifyKind(day.AddDays(-(((int)day.DayOfWeek + 6) % 7)), DateTimeKind.Unspecified); } }
    private static FlowLayoutPanel Bar(params Control[] controls) { var p = new FlowLayoutPanel { Dock = DockStyle.Top, AutoSize = true, WrapContents = true, Padding = new(6) }; p.Controls.AddRange(controls); return p; }
    private static DataGridView Grid(string name)
    {
        var g = new DataGridView { Name = name, Dock = DockStyle.Fill, AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.DisplayedCells }; RecordSelection.Configure(g);
        g.DataBindingComplete += (_, _) =>
        {
            var titles = new Dictionary<string, string> { ["Name"] = "Vardiya / şablon", ["TeamName"] = "Ekip", ["TeamCode"] = "Ekip kodu", ["Site"] = "Saha", ["LocalStart"] = "Başlangıç (İstanbul)", ["LocalEnd"] = "Bitiş (hariç)", ["StartMinute"] = "Başlangıç dakikası", ["DurationMinutes"] = "Süre dk", ["BreakMinutes"] = "Mola dk", ["RequiredCount"] = "Gereken kişi", ["AssignedCount"] = "Atanan kişi", ["MissingCount"] = "Eksik kişi", ["PlannedMinutes"] = "Planlanan net dk", ["CalendarMinutes"] = "Takvim dk", ["ProjectResponsible"] = "Güncel proje sorumlusu", ["Status"] = "Durum", ["CreatedBy"] = "Oluşturan", ["PublishedBy"] = "Yayınlayan", ["CancelledBy"] = "İptal eden", ["DecidedBy"] = "Karar veren", ["AD"] = "Ad", ["SOYAD"] = "Soyad", ["ShiftName"] = "Vardiya", ["IZINBASLANGIC"] = "Eski izin ilk gün", ["IZINBITIS"] = "Eski izin son gün (dahil)", ["Source"] = "Kaynak", ["PersonnelGroup"] = "Grup (0 Genel / 1 Joker)", ["PolicyVersion"] = "Takvim politika sürümü" };
            foreach (DataGridViewColumn c in g.Columns) { if (titles.TryGetValue(c.Name, out var title)) c.HeaderText = title; if (c.ValueType == typeof(Guid) || c.ValueType == typeof(byte[]) || c.Name is "CreateReason" or "StartUtc" or "EndUtc") c.Visible = false; if (c.ValueType == typeof(DateTime)) c.DefaultCellStyle.Format = "dd.MM.yyyy ddd HH:mm"; }
        };
        g.CellFormatting += (_, e) => { if (e.RowIndex < 0 || e.ColumnIndex < 0) return; if (g.Columns[e.ColumnIndex].Name == "Status") { e.Value = e.Value?.ToString() switch { "Draft" => "Taslak", "Published" => "Yayında", "Cancelled" => "İptal", "Requested" => "Talep", "Approved" => "Onaylı", "Rejected" => "Ret", var v => v }; e.FormattingApplied = true; } }; return g;
    }
    internal ScheduleCalendarForm(Guid project, UserSession user, bool plan, bool approve)
    {
        this.project = project; this.plan = plan; this.approve = approve; Session = user; PersistGridLayout = false; Text = "Muhasebe — Haftalık vardiya ve izin takvimi"; ClientSize = new(1240, 820); week.Value = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, DailyClosingService.BusinessZone).Date;
        var tabs = new TabControl { Dock = DockStyle.Fill }; void Tab(string title, DataGridView grid, params Control[] buttons) { var tab = new TabPage(title); tab.Controls.Add(grid); if (buttons.Length > 0) tab.Controls.Add(Bar(buttons)); tabs.TabPages.Add(tab); }
        Tab("Haftalık özet", board); Tab("Vardiyalar", shifts, create, copyWeek, add, publish, cancel); Tab("Vardiya personeli", assignments, remove); Tab("İzin talepleri", leaves, request, accept, reject, cancelLeave); Tab("Genel doğrudan izinler", legacy); Tab("Şablonlar", templates, newTemplate, editTemplate); Controls.Add(tabs); Controls.Add(note);
        board.DefaultCellStyle.WrapMode = DataGridViewTriState.True; board.AutoSizeRowsMode = DataGridViewAutoSizeRowsMode.AllCells; board.AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill;
        Button refresh = Button("Haftayı yükle"), previous = Button("← Önceki hafta"), next = Button("Sonraki hafta →"), close = Button("Kapat"); Controls.Add(Bar(new Label { Text = "Hafta (seçilen günün pazartesisi)", AutoSize = true }, week, team, history, previous, next, refresh, close));
        refresh.Click += async (_, _) => await ReloadAsync(); RefreshAction = ReloadAsync; previous.Click += async (_, _) => { week.Value = First.AddDays(-7); await ReloadAsync(); }; next.Click += async (_, _) => { week.Value = First.AddDays(7); await ReloadAsync(); }; close.Click += (_, _) => Close();
        copyWeek.Click += async (_, _) => { if (shifts.DataSource is not DataTable source) return; using var d = new WeekCopyDialog(project, User, First, source); d.SessionRevoked += (_, _) => NotifySessionRevoked(); d.ShowDialog(this); if (!IsDisposed) { if (d.Saved) week.Value = d.Target; await ReloadAsync(); } };
        create.Click += async (_, _) => { using var d = new ShiftCreateDialog(project, User, templateData, First); await DialogAsync(d); }; newTemplate.Click += async (_, _) => { using var d = new ShiftTemplateDialog(project, User, teamData, null); await DialogAsync(d); }; editTemplate.Click += async (_, _) => { if (Row(templates) is not { } r) return; using var d = new ShiftTemplateDialog(project, User, teamData, r); await DialogAsync(d); };
        add.Click += async (_, _) => await AssignAsync(); remove.Click += async (_, _) => await RemoveAsync(); publish.Click += async (_, _) => await ShiftStateAsync("Published"); cancel.Click += async (_, _) => await ShiftStateAsync("Cancelled"); request.Click += async (_, _) => { var person = PickPerson(); if (person == null) return; using var d = new LeaveRequestDialog(project, User, person); await DialogAsync(d); }; accept.Click += async (_, _) => await LeaveStateAsync("Approved"); reject.Click += async (_, _) => await LeaveStateAsync("Rejected"); cancelLeave.Click += async (_, _) => await LeaveStateAsync("Cancelled");
        foreach (var g in new[] { shifts, assignments, leaves, templates }) g.SelectionChanged += (_, _) => RefreshEditState(); ClientSizeChanged += (_, _) => note.MaximumSize = new(Math.Max(1, ClientSize.Width - 24), 0); Load += async (_, _) => await ReloadAsync(); SessionRevoked += (_, _) => Close(); PageRequested += (_, _) => Close();
    }
    protected override void OnLoad(EventArgs e) { base.OnLoad(e); MinimumSize = LogicalToDeviceUnits(new Size(820, 560)); }
    protected override void RefreshEditState()
    {
        bool ready = !IsOperationRunning && !loading; create.Enabled = copyWeek.Enabled = newTemplate.Enabled = request.Enabled = ready && plan; editTemplate.Enabled = ready && plan && Row(templates) != null; var s = Row(shifts); add.Enabled = publish.Enabled = ready && plan && s?.Field<string>("Status") == "Draft"; cancel.Enabled = ready && plan && s != null && s.Field<string>("Status") != "Cancelled"; remove.Enabled = ready && plan && Row(assignments) is { } a && a.Field<string>("Status") == "Draft" && a.IsNull("CancelledUtc"); var l = Row(leaves); accept.Enabled = reject.Enabled = ready && approve && l?.Field<string>("Status") == "Requested"; cancelLeave.Enabled = ready && approve && l != null && l.Field<string>("Status") is "Requested" or "Approved";
    }
    private async Task ReloadAsync()
    {
        if (loading) return; Guid? chosen = (team.SelectedItem as Team)?.Id; DateTime first = First; bool showHistory = history.Checked;
        loading = true; try { await RunOperationAsync(async ct => { var teams = await new ProjectWorkforceService(AppDatabase.ConnectionString, User).TeamsAsync(project, ct); var t = await Service.TemplatesAsync(project, ct); var data = await Service.WeekAsync(project, first, chosen, showHistory, ct); if (IsDisposed) return; teamData = teams; templateData = t; team.Items.Clear(); team.Items.Add(new Team(null, "Tüm ekipler")); foreach (DataRow row in teams.Rows) team.Items.Add(new Team(row.Field<Guid>("TeamId"), row["Code"] + " · " + row["Name"])); team.SelectedItem = team.Items.Cast<Team>().FirstOrDefault(x => x.Id == chosen) ?? team.Items[0]; shifts.DataSource = data.Shifts; assignments.DataSource = data.Assignments; leaves.DataSource = data.Leaves; legacy.DataSource = data.Legacy; templates.DataSource = t; board.DataSource = BuildBoard(first, data.Shifts, data.Leaves, data.Legacy); foreach (var g in new[] { board, shifts, assignments, leaves, legacy, templates }) g.ClearSelection(); note.Text = $"{first:dd.MM.yyyy} – {first.AddDays(6):dd.MM.yyyy} · Europe/Istanbul · Bitiş anı hariç. Gece vardiyası tek kayıttır; özette devam ettiği günlerde de gösterilir. Mola süreleri ve izin takvim dakikaları ücret/puantaj hesabı değildir. Yayında eksik kapasite olabilir. Son okuma: {DateTime.Now:HH:mm:ss}"; }); } finally { loading = false; if (!IsDisposed) RefreshEditState(); }
    }
    private static DataTable BuildBoard(DateTime first, DataTable shifts, DataTable leaves, DataTable legacy)
    {
        var result = new DataTable("Haftalık takvim"); result.Columns.Add("Ekip / kayıt türü"); for (int d = 0; d < 7; d++) result.Columns.Add(first.AddDays(d).ToString("ddd dd.MM"));
        foreach (var group in shifts.AsEnumerable().GroupBy(r => r.Field<Guid?>("TeamId")))
        { var values = new object[8]; values[0] = group.First().IsNull("TeamName") ? "Proje geneli" : group.First()["TeamCode"] + " · " + group.First()["TeamName"]; for (int d = 0; d < 7; d++) { var day = first.AddDays(d); values[d + 1] = string.Join("\n\n", group.Where(r => r.Field<DateTime>("LocalStart") < day.AddDays(1) && r.Field<DateTime>("LocalEnd") > day).Select(r => $"{r["Name"]} · {r["Site"]}\n{r.Field<DateTime>("LocalStart"):dd.MM HH:mm}–{r.Field<DateTime>("LocalEnd"):dd.MM HH:mm}\n{r["AssignedCount"]}/{r["RequiredCount"]} kişi · {(r.Field<string>("Status") switch { "Draft" => "Taslak", "Published" => "Yayında", _ => "İptal" })}")); } result.Rows.Add(values); }
        var summary = new object[8]; summary[0] = "İzin kayıtları"; for (int d = 0; d < 7; d++) { var day = first.AddDays(d); int Count(string state) => leaves.AsEnumerable().Count(r => r.Field<string>("Status") == state && r.Field<DateTime>("LocalStart") < day.AddDays(1) && r.Field<DateTime>("LocalEnd") > day); var old = legacy.AsEnumerable().Count(r => r.Field<DateTime>("IZINBASLANGIC") <= day && r.Field<DateTime>("IZINBITIS") >= day); summary[d + 1] = $"Onaylı: {Count("Approved")}\nTalep: {Count("Requested")}\nDoğrudan Genel: {old}"; }
        result.Rows.Add(summary); return result;
    }
    private ScopedPerson? PickPerson() { using var p = new CalendarPersonPicker(project, User); p.SessionRevoked += (_, _) => NotifySessionRevoked(); return p.ShowDialog(this) == DialogResult.OK ? p.SelectedPerson : null; }
    private async Task DialogAsync(SessionForm dialog) { dialog.SessionRevoked += (_, _) => NotifySessionRevoked(); dialog.ShowDialog(this); if (!IsDisposed) await ReloadAsync(); }
    private async Task ChangeAsync(Func<string, object> request) { await RunChangeOperationAsync(ct => CalendarCommands.RunAsync(request(RemoteApi.Reason), User, ct), "Takvim durumu kaydedildi."); if (!IsDisposed) await ReloadAsync(); }
    private async Task AssignAsync() { if (Row(shifts) is not { } s) return; Guid shift = s.Field<Guid>("ShiftId"); byte[] version = Version(s); var person = PickPerson(); if (person == null || IsDisposed) return; Guid id = Guid.NewGuid(); await ChangeAsync(reason => new Wire.ShiftPerson(project, shift, version, id, person.Id, person.Group, person.Version.ToArray(), reason)); }
    private async Task RemoveAsync() { if (Row(assignments) is not { } a || shifts.DataSource is not DataTable data) return; var s = data.AsEnumerable().SingleOrDefault(r => r.Field<Guid>("ShiftId") == a.Field<Guid>("ShiftId")); if (s == null) return; var shift = s.Field<Guid>("ShiftId"); var sv = Version(s); var id = a.Field<Guid>("ShiftAssignmentId"); var av = Version(a); await ChangeAsync(reason => new Wire.ShiftPersonCancel(project, shift, sv, id, av, reason)); }
    private async Task ShiftStateAsync(string state) { if (Row(shifts) is not { } s) return; Guid id = s.Field<Guid>("ShiftId"); var version = Version(s); if (state == "Published" && s.Field<int>("MissingCount") > 0 && MessageBox.Show(this, $"{s["MissingCount"]} kişi eksik. Eksik kapasiteyle yayınlansın mı? Yayından sonra değişiklik için iptal ve yeni vardiya gerekir.", "Vardiya kapasitesi", MessageBoxButtons.YesNo) != DialogResult.Yes) return; await ChangeAsync(reason => new Wire.ShiftState(project, id, version, state, reason)); }
    private async Task LeaveStateAsync(string state) { if (Row(leaves) is not { } l) return; Guid id = l.Field<Guid>("LeaveId"); var version = Version(l); await ChangeAsync(reason => new Wire.LeaveRequestState(project, id, version, state, reason)); }
}
